  if (!pool.length) { result = 'すべて出ました(「履歴を消す」でやり直し)'; K.invalidate(); return; }
  var index = pool[Roulette.pick(pool.length, function () { return random.next(); })];
  var target = Roulette.stopRotation(rot, index, items.length, random.next(), 4);
