  var pad = 12, cols = count <= 2 ? count : (count <= 6 ? 3 : 4), rows = Math.ceil(count / cols);
  var cell = Math.min((w - pad * 2) / cols, Math.max(80, (h - 140) / rows), 130), size = cell * 0.8;
