    if (flip.t >= FLIP_TIME) {
      side = flip.result;
      counts[side] += 1;
      recent.unshift(side === 0 ? '表' : '裏');
      recent = recent.slice(0, 20);
      save();
      flip = null;
      sound.play('coin');
