    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    K.fitText(t.name + '  セット ' + t.sets, x + cellW / 2, y + 10, cellW - 16, 16, true);
